import { Component, Element, Event, EventEmitter, h, Host, Prop } from '@stencil/core';
import { AvatarSize } from '../../types';

@Component({
  tag: 'groupui-avatar',
  styleUrl: 'avatar.scss',
  shadow: { delegatesFocus: true },
})
export class Avatar {
  /**
   * sets the avatar size
   */
  @Prop({ reflect: true }) readonly size: AvatarSize = 's';

  /**
   * activates an inverted presentation
   */
  @Prop({ reflect: true }) readonly inverted: boolean;

  /**
   * Initials to be shown instead of default icon
   */
  @Prop({ reflect: true }) readonly initials: string;

  /**
   * Image source of the image to be shown instead of default icon
   */
  @Prop({ reflect: true }) readonly imageSource: string;

  /**
   * Sets a title to the icon (when no image source or initials are given)
   */
  @Prop({ reflect: true }) readonly iconTitle: string;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  private content() {
    if (this.imageSource) return this.imageElement();
    if (this.initials) return this.initialsElement();

    return this.iconElement();
  }

  private iconElement() {
    return <groupui-icon name={'user-' + this.getPxValue(this.size)} title={this.iconTitle}></groupui-icon>;
  }

  private getPxValue(size) {
    switch (size) {
      case 'xs':
        return '16';
      case 's':
        return '16';
      case 'm':
        return '24';
      case 'l':
        return '32';
      case 'xl':
        return '48';
      default:
        return '24';
    }
  }

  private imageElement() {
    return <img src={this.imageSource} alt="Avatar" />;
  }

  private initialsElement() {
    return <span>{this.initials}</span>;
  }

  render() {
    return <Host>{this.content()}</Host>;
  }
}
